head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/buttonSet.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
scwin.notiId;
scwin.vSecugrpID = "";
scwin.strBzProcsNo, scwin.strProcsCd, scwin.strDtlSeq = "";
scwin.vScrenID = "ULDSTF20506_FILE.xml";
scwin.fn_SetPar;
scwin.isBefore = false;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_read = function() {
    trs_Read.Action = "/RealInvstg.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=realInvstgReadFile&bz_procs_no=" + scwin.strBzProcsNo + "&list_eligty_procs_cd=" + scwin.strProcsCd + "&file_seq=" + scwin.strDtlSeq;
    trs_Read.KeyValue = "JSP(O:pOutput2=dts_fileList)";
    trs_Read.Post();
};


//파일 다운로드
scwin.fn_filedown = function(bzProcsNo, procsNo, dtlSeq, fileSeq) {
    location.href = "/filedownload.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_08 + "&BZ_PROCS_NO=" + bzProcsNo + "&LIST_ELIGTY_PROCS_CD=" + procsNo + "&LIST_ELIGTY_INVSTG_DTL_SEQ=" + dtlSeq + "&ATTACH_FILE_SEQ=" + fileSeq + "&gubun=42";
};
scwin.fn_setDataHeader = function() {

    //dts_fileList.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 

};
scwin.fn_searchCode = function() {
    var url = "/CodeAction.do?method=listCodeValueNameM&inputMessageId=CODE_M_IN&outputMessageId=CODE_M_OUT" + "&CD_ID_M='LIST_ELIGTY_FILE_TP_CD'";
    dts_Cod.DataID = encodeURI(url);
    dts_Cod.reset();
    var strCbdReason = "' ':"; //초기값

    for (k = 1; k <= dts_Cod.getTotalRow(); k++) {
        strCbdReason = strCbdReason + (strCbdReason == "" ? "" : ",") + dts_Cod.getCellData(k, "VALUE") + ":" + dts_Cod.getCellData(k, "TEXT");
    }
    $c.cm.setColumnProp(grd_userlist, 'LIST_ELIGTY_FILE_TP_CD', 'Data', strCbdReason);
};
scwin.trs_Read_OnLoadError = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0002", ""));
};
scwin.grd_userlist_OnDblClick = function(row, colid) {
    var bzProcsNo = dts_fileList.getCellData(row, "BZ_PROCS_NO");
    var procsNo = dts_fileList.getCellData(row, "LIST_ELIGTY_PROCS_CD");
    var dtlSeq = dts_fileList.getCellData(row, "LIST_ELIGTY_INVSTG_DTL_SEQ");
    var fileSeq = dts_fileList.getCellData(row, "ATTACH_FILE_SEQ");
    if (dts_fileList.getRowStatus(dts_fileList.getRowPosition()) == 0) {
        $c.elw.fn_filedown(bzProcsNo, procsNo, dtlSeq, fileSeq);
    }
};
scwin.btn_close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_Top);
    scwin.strBzProcsNo = $c.stf.getQuery(frame.srcUrl, "BZ_PROCS_NO");
    scwin.strProcsCd = $c.stf.getQuery(frame.srcUrl, "LIST_ELIGTY_PROCS_CD");
    var tempDtlSeq = $c.stf.getQuery(frame.srcUrl, "LIST_ELIGTY_INVSTG_DTL_SEQ");
    if (tempDtlSeq != "") {
        var splitStr = tempDtlSeq.split(",");
        if (splitStr.length > 1) {
            for (var i = 0, j = splitStr.length; i < j; i++) {
                if (i != 0) scwin.strDtlSeq += ",";
                scwin.strDtlSeq += "'" + splitStr[i] + "'";
            }
        } else {
            scwin.strDtlSeq = tempDtlSeq;
        }
    }
    $c.elw.fn_searchCode();
    scwin.fn_read();
};
